import { apiFetch } from "./client";
import type { Product } from "@/lib/types/product";

export interface ProductPage {
  items: Product[];
  page: number;
  size: number;
  totalItems: number;
  totalPages: number;
}

// Accepts the exact string generated by toApiSearch()
export async function getProducts(apiQueryString: string = ""): Promise<ProductPage> {
  return apiFetch<ProductPage>(`/products${apiQueryString}`);
}

// Alias for older components
export const fetchProducts = getProducts;

export async function getProduct(slug: string): Promise<Product | null> {
  return apiFetch<Product | null>(`/products/${encodeURIComponent(slug)}`, { allow404: true });
}

// Legacy helper for the home page (app/page.tsx)
export async function getNewArrivals(limit: number = 4): Promise<Product[]> {
  try {
    // Fetches the newest items that have an image to display on the home page carousel/grid
    const page = await getProducts(`?sort=newest&size=${limit}&withImage=true`);
    return page.items || [];
  } catch (error) {
    console.error("Failed to fetch new arrivals:", error);
    return [];
  }
}